{
  "cases": [
    {
      "id": "C1",
      "instrument_review": "The 100 puzzles and exact-grid scoring define a narrow performance measure. The 70% result describes one reported run. Repetition, score consistency, puzzle selection, and conditions needed for fair comparisons are not documented sufficiently.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is neither documented nor explicitly ruled out."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish consistency across runs."
        }
      ]
    },
    {
      "id": "C2",
      "instrument_review": "Exact-grid scoring supports reporting performance on the specified puzzles, but the single evaluation provides no evidence about variation across runs. Puzzle selection and controls for fair system comparisons remain unspecified.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly excludes repeated evaluations."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated runs, score stability remains unknown; instability is not demonstrated either."
        }
      ]
    },
    {
      "id": "C3",
      "instrument_review": "Repeated evaluations held the listed conditions constant, and the observed range meets the report's explicit stability criterion. This supports consistency for this system and these conditions. Puzzle selection, fairness across other systems, and consistency beyond these evaluations remain unestablished.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage documents repeated evaluations under matching conditions and reports their scores."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed two-percentage-point range meets the stated criterion."
        }
      ]
    },
    {
      "id": "C4",
      "instrument_review": "Repeated evaluations controlled the listed conditions but produced a range that fails the report's stability criterion. The initial 70% score therefore gives an incomplete account of observed performance. The cause of variation and controls for fair comparisons across systems remain unknown.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations under matching conditions are explicitly documented."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed range exceeds the explicit stability threshold."
        }
      ]
    },
    {
      "id": "C5",
      "instrument_review": "Installation instructions document setup, but add no evidence about score consistency or comparative performance. Exact-grid scoring and the single reported result support only the stated narrow observation. Repetition, puzzle selection, and comparison controls remain insufficiently documented.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "The added installation documentation does not establish that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "Setup instructions supply no repeated-run findings supporting stability."
        }
      ]
    },
    {
      "id": "C6",
      "instrument_review": "The reported counts, exact-grid scoring, and fixed instructions support A's higher performance on the evaluated puzzles, matching the intended use. Repeated-run consistency, puzzle selection, and other resource controls are unspecified. Findings about performance across domains are absent.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the reported conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish comparative general intelligence across domains."
        }
      ]
    },
    {
      "id": "C7",
      "instrument_review": "The evaluation supports a comparison on the tested grid puzzles, but its intended selection use extends beyond the supplied evidence. Fixed instructions and exact-grid scoring clarify part of the comparison; consistency, other resource controls, and evidence across domains remain missing.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The observed counts support A's better performance on these puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a broader intended use does not supply evidence for general intelligence across domains."
        }
      ]
    },
    {
      "id": "C8",
      "instrument_review": "The later preregistered randomized trial supplies direct comparative evidence for the intended workshop decision-correctness use. Blinded correctness checking and the reported uncertainty interval strengthen interpretation of A's advantage. Initial test scores alone do not establish workshop improvement. Generalization beyond the studied conditions, time effects, and safety effects remain unestablished.",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "No initial evidence connecting those scores to improved real workshop decisions is supplied."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%. The reported uncertainty interval for the difference was 12 to 28 percentage points.",
          "reason": "The randomized trial reports higher correctness with A and an interval wholly favoring A for the studied workshop conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness findings alone do not establish an improvement in workplace safety."
        }
      ]
    }
  ],
  "closing_note": "No instructions required clarification. Missing evidence was distinguished from explicit conflicting evidence."
}
